-- Verification (expect: words 50 | with_situation 50 | with_gap_rows 50 | gap_rows 182 | with_spelling 50)
select
  count(*) as words,
  count(*) filter (where senses->0 ? 'situationDistractors') as with_situation,
  count(*) filter (where senses->0 ? 'gapDistractors') as with_gap_rows,
  coalesce(sum(jsonb_array_length(senses->0->'gapDistractors')),0) as gap_rows,
  count(*) filter (where senses->0 ? 'spellingErrors') as with_spelling
from public.vocabulary_items
where vocabulary_id in ('vocab_leisure','vocab_preference','vocab_avoid','vocab_afford','vocab_deny','vocab_permit','vocab_arrange','vocab_urge','vocab_recommend','vocab_demand','vocab_threaten','vocab_resent','vocab_regret','vocab_unfamiliar','vocab_racquet','vocab_opponent','vocab_intense','vocab_tournament','vocab_determined','vocab_discipline','vocab_goal_oriented','vocab_achievement','vocab_elite','vocab_overwhelming','vocab_generation','vocab_challenge','vocab_solution','vocab_pastime','vocab_feat','vocab_regardless','vocab_monetary','vocab_estimated','vocab_struggle','vocab_minimum','vocab_championship','vocab_competitor','vocab_relatively','vocab_patience','vocab_atmosphere','vocab_incredible','vocab_criteria','vocab_historic','vocab_selection','vocab_produce','vocab_craftspeople','vocab_significant','vocab_expansion','vocab_reputation','vocab_reasonable','vocab_antiques') and status='live';
